/* Account menu for a sidebar footer. Expanded: name + role. Collapsed (inside a
 * collapsed SideNav or the legacy app-shell rail): avatar only. */
.user-menu { min-inline-size: 0; }

.user-menu-trigger {
  display: flex; align-items: center; gap: var(--space-2);
  inline-size: 100%; min-inline-size: 0;
  padding: var(--space-1) var(--space-2);
  border: none; border-radius: var(--radius-full);
  background: transparent; color: var(--foreground); font-family: inherit;
  text-align: start; cursor: pointer; transition: background var(--duration-fast);
}
/* NO FILL ON HOVER. The trigger is the account, not a menu row: the pointer
 * passes over it on the way to everything else in the footer, and a rail that
 * lights up under the pointer reads as something being chosen (owner,
 * 2026-08-29). Open still shows, because that IS a state. */
.user-menu-trigger[data-open] { background: var(--accent); }
.user-menu-trigger:focus-visible { outline: var(--focus-ring); outline-offset: var(--ring-offset); }

/* THE AVATAR IS THE PERSON, AND IT SHOWS IN BOTH STATES. It used to be
 * `display: none` unless the rail was collapsed, so the expanded footer — the
 * state a product is in almost all the time — had a name and a role and no
 * face at all (owner, 2026-08-29). Collapsed it grows to the rail's item size;
 * expanded it stays the md avatar the trigger asks for. */

.user-menu-trigger-text { flex: 1; display: flex; flex-direction: column; min-inline-size: 0; }
.user-menu-trigger-name {
  font-size: var(--font-sm); font-weight: var(--font-weight-regular); line-height: var(--leading-tight);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.user-menu-trigger-role {
  font-size: var(--font-xs); color: var(--muted-foreground); line-height: var(--leading-tight);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}

/* Collapsed rail: avatar only (works inside a collapsed SideNav or the app-shell). */
.side-nav[data-collapsed] .user-menu,
.app-shell[data-sidebar-collapsed] .user-menu { display: flex; justify-content: center; }
.side-nav[data-collapsed] .user-menu-avatar,
.app-shell[data-sidebar-collapsed] .user-menu-avatar {
  display: grid; inline-size: var(--sidebar-rail-item-size); block-size: var(--sidebar-rail-item-size);
}
.side-nav[data-collapsed] .user-menu-trigger-text,
.app-shell[data-sidebar-collapsed] .user-menu-trigger-text { display: none; }
.side-nav[data-collapsed] .user-menu-trigger,
.app-shell[data-sidebar-collapsed] .user-menu-trigger {
  inline-size: var(--sidebar-rail-item-size); block-size: var(--sidebar-rail-item-size);
  padding: 0; justify-content: center;
}

import "./UserMenu.css";
import { Avatar } from "../Avatar";
import { Dropdown, DropdownItem } from "../Dropdown";
import { type IconName } from "../Icon";

export type UserMenuAction = { id: string; label: string; icon?: IconName; onSelect: () => void };

type Props = {
  name: string;
  /** Secondary line under the name (e.g. role). */
  role?: string;
  avatarSrc?: string;
  /** Menu entries shown in the dropdown. */
  actions: UserMenuAction[];
  menuLabel?: string;
};

/** Account trigger for a sidebar footer: name + role expanded, avatar-only when
 *  the surrounding rail is collapsed (reacts to a collapsed SideNav / app shell).
 *  Presentation-only — the consumer supplies the user and the menu actions. 
 *
 * Copy: the trigger names the person, and the items are verbs — "Sign out", not
 * "Sign-out".
 */
export function UserMenu({ name, role, avatarSrc, actions, menuLabel = "Account menu" }: Props) {
  return (
    <Dropdown
      className="user-menu"
      align="start"
      trigger={({ isOpen, ...triggerProps }) => (
        <button type="button" className="user-menu-trigger" data-open={isOpen || undefined} aria-label={menuLabel} {...triggerProps}>
          <Avatar name={name} src={avatarSrc} size="md" className="user-menu-avatar" />
          <span className="user-menu-trigger-text">
            <span className="user-menu-trigger-name">{name}</span>
            {role && <span className="user-menu-trigger-role">{role}</span>}
          </span>
        </button>
      )}
    >
      {actions.map((a) => (
        <DropdownItem key={a.id} icon={a.icon} onClick={a.onSelect}>{a.label}</DropdownItem>
      ))}
    </Dropdown>
  );
}
